# ── Lambda calculus encoding (Haskell's lambdas are just nested functions) ─────

class Lambda:
    def __init__(self, body):
        self.body = body

    def call(self, arg):      # noqa: A003
        return self.body(arg)

    def __call__(self, arg):  # noqa: A003
        return self.call(arg)

    def bind(self, var, val):
        return Lambda(lambda x: self.call(Lambda(val).bind(var, x)))

    def apply(self, func):
        return Lambda(
            lambda a: Lambda(func(a)).call(self.a)
        )

    def fmap(self, fun):
        return Lambda(
            lambda x: fun(self.call(x))
        )


# ── Partial function application (lambda + stored args) ───────────────────────

def partial(fun, /, *args):
    def _fun(*more_args):
        return fun(*(args + more_args))

    return _fun



# ── Trampoline: tail-recursive generator-based iteration using `yield from` ─────

class Trampoline(Generic[T]):
    def __init__(self, it: T):
        self.it = it

    def __iter__(self):
        while True:
            try:
                yield next(self.it)
            except StopIteration:
                break


@functools.cache
def factorial(n: int) -> int:
    if n == 0 or n == 1:
        yield n
    else:
        for i in range(n):
            yield i+1
            yield from factorial(i)



